const FORBIDDEN_PERIPHERAL_CASES = [
  "2019노320, 2019전노22(병합)",
  "2019도14341, 2019전도130",
  "2018고합143, 2018전고11(병합)",
];

function cases(queries, expectedTopCaseNumbers) {
  return queries.map((query) => ({
    query,
    expectedTopCaseNumbers,
    forbiddenTopCaseNumbers: FORBIDDEN_PERIPHERAL_CASES,
    expectEmpty: false,
  }));
}

